using System;using MySql.Data.MySqlClient;namespace TheRanger{public partial class OwnerDashboard:System.Web.UI.Page{protected void Page_Load(object s,EventArgs e){if(Session["UserRole"]==null||Session["UserRole"].ToString()!="Owner"){Response.Redirect("Login.aspx");return;}if(!IsPostBack){litName.Text=Server.HtmlEncode(Session["UserName"].ToString());LoadData();}}void LoadData(){int id=Convert.ToInt32(Session["UserId"]);using(var c=Database.GetConnection()){c.Open();Set(c,"SELECT COUNT(*) FROM Accommodation WHERE owner_id=@id","@id",id,litAccommodation);Set(c,"SELECT COUNT(*) FROM GameDrive WHERE owner_id=@id","@id",id,litDrives);Set(c,"SELECT (SELECT COUNT(*) FROM Bookings b JOIN Accommodation a ON a.accommodation_id=b.accommodation_id WHERE a.owner_id=@id AND b.booking_status='Pending')+(SELECT COUNT(*) FROM DriveBookings d JOIN GameDrive g ON g.game_drive_id=d.game_drive_id WHERE g.owner_id=@id AND d.booking_status='Pending')","@id",id,litPending);Set(c,"SELECT (SELECT COUNT(*) FROM Bookings b JOIN Accommodation a ON a.accommodation_id=b.accommodation_id WHERE a.owner_id=@id AND b.booking_status='Confirmed')+(SELECT COUNT(*) FROM DriveBookings d JOIN GameDrive g ON g.game_drive_id=d.game_drive_id WHERE g.owner_id=@id AND d.booking_status='Confirmed')","@id",id,litConfirmed);}}void Set(MySqlConnection c,string q,string p,int v,System.Web.UI.WebControls.Literal l){using(var cmd=new MySqlCommand(q,c)){cmd.Parameters.AddWithValue(p,v);l.Text=cmd.ExecuteScalar().ToString();}}}}
